//! Core telemetry domain types representing one system snapshot.

use serde::{Deserialize, Serialize};

/// Whether telemetry came from the elevated daemon or local in-process readers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
pub enum SourceOrigin {
    /// Read directly inside the unprivileged process (no daemon required).
    #[default]
    Local,
    /// Received from the `hw-watcher` daemon over D-Bus.
    Daemon,
    /// Synthetic telemetry generated by `--simulate`.
    Simulated,
}

/// Capabilities actually active in the current source.
#[allow(clippy::struct_excessive_bools)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
pub struct Capabilities {
    /// GPU telemetry available (NVML, or AMD/Intel via DRM sysfs).
    pub nvml: bool,
    /// RAPL CPU package power readable.
    pub rapl: bool,
    /// `k10temp` CPU temperature readable.
    pub hwmon_cpu: bool,
    /// `nct6687` board telemetry readable.
    pub hwmon_board: bool,
    /// `/proc/meminfo` system RAM readable.
    pub meminfo: bool,
    /// BAR0 VRAM/hotspot temperatures readable.
    pub bar0: bool,
    /// NVAPI core voltage readable.
    pub nvapi_voltage: bool,
}

/// System RAM usage in MiB.
#[derive(Debug, Clone, Copy, PartialEq, Default, Serialize, Deserialize)]
pub struct MemorySample {
    /// Used RAM in MiB (`total - available`).
    pub used_mib: Option<f64>,
    /// Total physical RAM in MiB.
    pub total_mib: Option<f64>,
}

impl MemorySample {
    /// Returns RAM utilization percentage in `0.0..=100.0` when both values are valid.
    pub fn used_pct(&self) -> Option<f64> {
        pct_ratio(self.used_mib, self.total_mib)
    }
}

/// NVIDIA GPU telemetry (NVML + optional BAR0/NVAPI).
#[derive(Debug, Clone, Copy, PartialEq, Default, Serialize, Deserialize)]
pub struct GpuSample {
    /// GPU core temperature in °C.
    pub temp_c: Option<f64>,
    /// Instantaneous board power draw in watts.
    pub power_w: Option<f64>,
    /// Averaged board power draw in watts.
    pub avg_power_w: Option<f64>,
    /// Active power limit in watts.
    pub power_limit_w: Option<f64>,
    /// GPU compute/graphics utilization percentage.
    pub usage_pct: Option<f64>,
    /// Graphics clock in MHz.
    pub clock_mhz: Option<f64>,
    /// Memory clock in MHz.
    pub clock_mem_mhz: Option<f64>,
    /// Used GPU VRAM in MiB.
    pub vram_used_mib: Option<f64>,
    /// Total GPU VRAM in MiB.
    pub vram_total_mib: Option<f64>,
    /// Core voltage in volts (NVAPI, optional).
    pub voltage_v: Option<f64>,
    /// VRAM junction temperature in °C (BAR0, elevated only).
    pub vram_temp_c: Option<f64>,
    /// GPU hotspot temperature in °C (BAR0, elevated only).
    pub hotspot_temp_c: Option<f64>,
}

impl GpuSample {
    /// Returns VRAM utilization percentage in `0.0..=100.0` when both values are valid.
    pub fn vram_pct(&self) -> Option<f64> {
        pct_ratio(self.vram_used_mib, self.vram_total_mib)
    }
}

/// CPU telemetry (RAPL power + hwmon Tctl).
#[derive(Debug, Clone, Copy, PartialEq, Default, Serialize, Deserialize)]
pub struct CpuSample {
    /// Package power draw in watts (RAPL).
    pub package_w: Option<f64>,
    /// Tctl temperature in °C (`k10temp`).
    pub tctl_c: Option<f64>,
}

/// Motherboard `hwmon` (`nct6687`) telemetry resolved by label.
#[derive(Debug, Clone, Copy, PartialEq, Default, Serialize, Deserialize)]
pub struct BoardSample {
    /// +12V rail voltage in volts.
    pub v12_v: Option<f64>,
    /// +5V rail voltage in volts.
    pub v5_v: Option<f64>,
    /// +3.3V rail voltage in volts.
    pub v3_3_v: Option<f64>,
    /// CPU Vcore in volts.
    pub vcore_v: Option<f64>,
    /// CPU `SoC` voltage in volts.
    pub soc_v: Option<f64>,
    /// DRAM voltage in volts.
    pub dram_v: Option<f64>,
    /// VRM MOS temperature in °C.
    pub vrm_mos_c: Option<f64>,
    /// CPU socket temperature in °C.
    pub cpu_socket_c: Option<f64>,
    /// System temperature in °C.
    pub system_c: Option<f64>,
    /// PCH temperature in °C.
    pub pch_c: Option<f64>,
    /// `PCIe` x1 slot temperature in °C.
    pub pcie_x1_c: Option<f64>,
    /// CPU fan speed in RPM.
    pub cpu_fan_rpm: Option<f64>,
    /// System fan 1 speed in RPM.
    pub sys_fan1_rpm: Option<f64>,
    /// System fan 3 speed in RPM.
    pub sys_fan3_rpm: Option<f64>,
}

/// Complete telemetry snapshot at one point in time.
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct Sample {
    /// Unix timestamp in milliseconds.
    pub timestamp_ms: u64,
    /// Origin of this snapshot.
    pub origin: SourceOrigin,
    /// Capabilities active when this snapshot was captured.
    pub caps: Capabilities,
    /// Primary GPU telemetry, if a supported GPU is present.
    pub gpu: Option<GpuSample>,
    /// Primary or aggregated CPU telemetry.
    pub cpu: CpuSample,
    /// Per-CPU telemetry when one or more CPUs are discovered.
    #[serde(default)]
    pub cpus: Vec<CpuSample>,
    /// Per-GPU telemetry when one or more GPUs are discovered.
    #[serde(default)]
    pub gpus: Vec<GpuSample>,
    /// System RAM telemetry.
    pub memory: MemorySample,
    /// Motherboard telemetry.
    pub board: BoardSample,
}

impl Sample {
    /// Returns per-CPU readings, falling back to `[self.cpu]` when `cpus` is empty.
    pub fn effective_cpus(&self) -> &[CpuSample] {
        if !self.cpus.is_empty() {
            &self.cpus
        } else if self.cpu.package_w.is_some() || self.cpu.tctl_c.is_some() {
            std::slice::from_ref(&self.cpu)
        } else {
            &[]
        }
    }

    /// Returns per-GPU readings, falling back to `self.gpu` when `gpus` is empty.
    pub fn effective_gpus(&self) -> &[GpuSample] {
        if !self.gpus.is_empty() {
            &self.gpus
        } else if let Some(gpu) = &self.gpu {
            std::slice::from_ref(gpu)
        } else {
            &[]
        }
    }

    /// Returns summed CPU + GPU power in watts when at least one CPU and one GPU report power.
    pub fn total_power_w(&self) -> Option<f64> {
        let cpu_w = sum_opt(self.effective_cpus().iter().filter_map(|c| c.package_w))?;
        let gpu_w = sum_opt(self.effective_gpus().iter().filter_map(|g| g.power_w))?;
        Some(cpu_w + gpu_w)
    }

    /// Returns the highest CPU or GPU temperature when at least one reading is available.
    pub fn peak_temp_c(&self) -> Option<f64> {
        self.effective_cpus()
            .iter()
            .filter_map(|c| c.tctl_c)
            .chain(self.effective_gpus().iter().filter_map(|g| g.temp_c))
            .reduce(f64::max)
    }
}

fn sum_opt(mut iter: impl Iterator<Item = f64>) -> Option<f64> {
    let first = iter.next()?;
    Some(iter.fold(first, |acc, x| acc + x))
}

fn pct_ratio(used: Option<f64>, total: Option<f64>) -> Option<f64> {
    let used = used?;
    let total = total?;
    if !used.is_finite() || !total.is_finite() || total <= 0.0 {
        return None;
    }
    Some(((used / total) * 100.0).clamp(0.0, 100.0))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn total_power_requires_both_cpu_and_gpu() {
        let mut s = Sample::default();
        assert_eq!(s.total_power_w(), None);

        s.gpu = Some(GpuSample {
            power_w: Some(120.0),
            ..Default::default()
        });
        assert_eq!(s.total_power_w(), None);

        s.cpu.package_w = Some(45.0);
        assert_eq!(s.total_power_w(), Some(165.0));
    }

    #[test]
    fn memory_and_vram_pct_handle_zero_and_valid_totals() {
        let m_zero = MemorySample {
            used_mib: Some(100.0),
            total_mib: Some(0.0),
        };
        assert_eq!(m_zero.used_pct(), None);

        let gpu = GpuSample {
            vram_used_mib: Some(6144.0),
            vram_total_mib: Some(24576.0),
            ..Default::default()
        };
        assert_eq!(gpu.vram_pct(), Some(25.0));
    }

    #[test]
    fn multi_cpu_and_gpu_aggregate_power_and_peak_temp() {
        let s = Sample {
            cpus: vec![
                CpuSample {
                    package_w: Some(40.0),
                    tctl_c: Some(58.0),
                },
                CpuSample {
                    package_w: Some(55.0),
                    tctl_c: Some(67.0),
                },
            ],
            gpus: vec![
                GpuSample {
                    power_w: Some(180.0),
                    temp_c: Some(62.0),
                    ..Default::default()
                },
                GpuSample {
                    power_w: Some(120.0),
                    temp_c: Some(71.0),
                    ..Default::default()
                },
            ],
            ..Default::default()
        };
        assert_eq!(s.total_power_w(), Some(395.0));
        assert_eq!(s.peak_temp_c(), Some(71.0));
    }
}
